         <p class="intro">
           Share your contact details and our support team will follow up with the best next step.
         </p>

         <form id="support-form" novalidate>
           <p class="required-note" id="required-note">
             Required fields are marked with an asterisk.
           </p>

           <div class="form-field">
             <label for="full-name">
               Full name <span class="required-marker" aria-hidden="true">*</span>
             </label>
             <input
               id="full-name"
               name="full-name"
               type="text"
               autocomplete="name"
               required
               aria-describedby="required-note"
             >
           </div>

           <div class="form-field">
             <label for="email">
               Email address <span class="required-marker" aria-hidden="true">*</span>
             </label>
             <input
               id="email"
               name="email"
               type="email"
               autocomplete="email"
               required
               aria-describedby="required-note"
             >
           </div>

           <div class="form-field">
             <label for="phone">Phone number (optional)</label>
             <input
               id="phone"
               name="phone"
               type="tel"
               autocomplete="tel"
               aria-describedby="phone-help"
             >
             <p class="helper-text" id="phone-help">
               Format: 555-123-4567 or +1 555-123-4567.
             </p>
           </div>

           <div class="actions">
             <button type="submit">Send support request</button>
           </div>

           <p class="form-status" role="status" aria-atomic="true"></p>
         </form>
       </section>
     </main>

     <script>
       const form = document.querySelector("#support-form");
       const statusMessage = form.querySelector("[role='status']");
       const fields = {
         fullName: document.querySelector("#full-name"),
         email: document.querySelector("#email"),
         phone: document.querySelector("#phone"),
       };

       function setFieldError(input, message) {
         let error = document.querySelector(`#${input.id}-error`);

         if (!error) {
           error = document.createElement("p");
           error.id = `${input.id}-error`;
           error.className = "field-error";
           input.insertAdjacentElement("afterend", error);
         }

         error.textContent = message;
         input.setAttribute("aria-invalid", "true");

         const describedBy = new Set((input.getAttribute("aria-describedby") || "").split(/\s+/).filter(Boolean));
         describedBy.add(error.id);
         input.setAttribute("aria-describedby", Array.from(describedBy).join(" "));
       }

       function clearFieldError(input) {
         const error = document.querySelector(`#${input.id}-error`);

         if (error) {
           error.remove();
         }

         input.removeAttribute("aria-invalid");

         const describedBy = (input.getAttribute("aria-describedby") || "")
           .split(/\s+/)
           .filter((id) => id && id !== `${input.id}-error`);

         if (describedBy.length) {
           input.setAttribute("aria-describedby", describedBy.join(" "));
         } else {
           input.removeAttribute("aria-describedby");
         }
       }

       function isValidPhone(value) {
         return value === "" || /^\+?\d[\d\s().-]{6,}\d$/.test(value);
       }

       function validateForm() {
         const invalidFields = [];
         const fullName = fields.fullName.value.trim();
         const email = fields.email.value.trim();
         const phone = fields.phone.value.trim();

         Object.values(fields).forEach(clearFieldError);
         statusMessage.textContent = "";

         if (!fullName) {
           setFieldError(fields.fullName, "Error: Enter your full name.");
           invalidFields.push(fields.fullName);
         }

         if (!email) {
           setFieldError(fields.email, "Error: Enter your email address.");
           invalidFields.push(fields.email);
         } else if (!fields.email.validity.valid) {
           setFieldError(fields.email, "Error: Enter a valid email address, like name@example.com.");
           invalidFields.push(fields.email);
         }

         if (!isValidPhone(phone)) {
           setFieldError(fields.phone, "Error: Enter a phone number in the format 555-123-4567.");
           invalidFields.push(fields.phone);
         }

         return invalidFields;
       }

       Object.values(fields).forEach((input) => {
         input.addEventListener("input", () => {
           clearFieldError(input);
           statusMessage.textContent = "";
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         const invalidFields = validateForm();

         if (invalidFields.length) {
           invalidFields[0].focus();
           return;
         }

         statusMessage.textContent = "Support request ready to send. Thanks for reaching out.";
         form.reset();
       });
     </script>
   </body>
 </html>

