 <!doctype html>
 <html lang="en">
   <head>
     <meta charset="utf-8">
     <meta name="viewport" content="width=device-width, initial-scale=1">
     <title>Support contact form</title>
     <style>
       :root {
         color-scheme: dark;
         --bg: #070b14;
         --panel: #111827;
         --panel-strong: #172033;
         --text: #f8fafc;
         --muted: #aeb8c8;
         --border: #334155;
         --accent: #6ee7f9;
         --accent-strong: #22d3ee;
         --error: #fca5a5;
         --error-bg: #3b1116;
         --success: #86efac;
         --shadow: 0 24px 70px rgba(0, 0, 0, 0.42);
       }

       * {
         box-sizing: border-box;
       }

       body {
         min-height: 100vh;
         margin: 0;
         font-family:
           Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
           "Segoe UI", sans-serif;
         line-height: 1.5;
         color: var(--text);
