         box-shadow: var(--shadow);
       }

       .eyebrow {
         margin: 0 0 0.5rem;
         color: var(--accent);
         font-size: 0.78rem;
         font-weight: 800;
         letter-spacing: 0.12em;
         text-transform: uppercase;
       }

       h1 {
         margin: 0;
         font-size: clamp(2rem, 7vw, 3.5rem);
         line-height: 1.05;
